// ==== SIZE-SCALE COMPARISON CHART PROPERTIES ====
//
// SizeScaleComparisonChart — N images sized by value. Value position rides
// the standard `dataLabels.position` dot-path (enum top | bottom | center).
// The only chart-specific row is the secondary-text toggle.
_defineProperty(ChartPropertiesName, "SECONDARY_LABEL_SHOW", "secondarylabel.show");
// ==== SIZE-SCALE SHAPE COMPARISON CHART PROPERTIES ====
//
// SizeScaleShapeComparisonChart — N CSS shapes (circle | rectangle |
// polygon) sized by value instead of raster images. `shapeConfig.shape`
// picks the value-shape; `barBackground.show` + `barBackground.shape` add a
// max-sized neutral backdrop shape with the value-shape bottom-aligned
// inside it. Value position / secondary text reuse the size-scale rows.
_defineProperty(ChartPropertiesName, "SHAPE_CONFIG_SHAPE", "shapeConfig.shape");
_defineProperty(ChartPropertiesName, "BAR_BACKGROUND_SHOW", "barBackground.show");
_defineProperty(ChartPropertiesName, "BAR_BACKGROUND_SHAPE", "barBackground.shape");
// ==== CURRENCY CHART PROPERTIES ====
//
// SimpleCurrencyChart — proportional currency-share strip. Labels and
// values live in alternating top/bottom callouts, so there is no
// position enum. Knobs below control strip geometry + connector look.
_defineProperty(ChartPropertiesName, "CURRENCY_SEGMENT_GAP", "currencyConfig.segmentGap");
_defineProperty(ChartPropertiesName, "CURRENCY_STRIP_HEIGHT_PCT", "currencyConfig.stripHeightPct");
_defineProperty(ChartPropertiesName, "CURRENCY_CONNECTOR_STYLE", "currencyConfig.connectorStyle");
_defineProperty(ChartPropertiesName, "CURRENCY_CONNECTOR_THICKNESS", "currencyConfig.connectorThickness");
_defineProperty(ChartPropertiesName, "CURRENCY_CALLOUT_MAX_WIDTH", "currencyConfig.calloutMaxWidth");
_defineProperty(ChartPropertiesName, "CURRENCY_MIN_SEGMENT_WIDTH", "currencyConfig.minSegmentWidth");
// ==== ICON-FILL CHART PROPERTIES ====
//
// FillCompareChart (variant 2 of the icon-fill family) — N icons
// side-by-side, each partially filled by its own independent value%.
// Geometry + divider/callout knobs live under `iconconfig.*`. No
// value-position enum (the divider+callout occupies that slot).
_defineProperty(ChartPropertiesName, "ICONFILL_FILL_DIRECTION", "iconconfig.fillDirection");
// bottom-up | top-down
_defineProperty(ChartPropertiesName, "ICONFILL_BACKGROUND_OPACITY", "iconconfig.backgroundOpacity");
// 0..1 — gray under-shape opacity
_defineProperty(ChartPropertiesName, "ICONFILL_ICON_PADDING", "iconconfig.iconPadding");
// px gap between repeated icons (barSimpleIconFill)
_defineProperty(ChartPropertiesName, "ICONFILL_BAR_SIZE", "iconconfig.barSize");
// 10..100 — icon height as % of the row (barSimpleIconFill)
_defineProperty(ChartPropertiesName, "ICONFILL_DIVIDER_STYLE", "iconconfig.dividerStyle");
// dashed | dotted | solid
_defineProperty(ChartPropertiesName, "ICONFILL_DIVIDER_COLOR", "iconconfig.dividerColor");
// item | theme
_defineProperty(ChartPropertiesName, "ICONFILL_DIVIDER_CALLOUT_FORMAT", "iconconfig.dividerCalloutFormat");
// percent | value | currency
// Top-level connector-line toggle — currently used by icon-fill (gated on
// dataLabels.position === "outside"); mirrors the funnel pattern. Chart
// variants that need a NESTED connectorLine (waterfall, comparison) use
// their own constants above.
_defineProperty(ChartPropertiesName, "CONNECTOR_LINE_SHOW", "connectorLine.show");
// ==== STATIC VALUE CONSTANTS (not property paths) ====
// ---- Animation Values ----
_defineProperty(ChartPropertiesName, "ANIMATION_ALL", "all");
_defineProperty(ChartPropertiesName, "ANIMATION_SEQUENTIAL", "sequential");
_defineProperty(ChartPropertiesName, "ANIMATION_OFF", "off");
// ---- Bar Style Values ----
_defineProperty(ChartPropertiesName, "BAR_STYLE_SOLID", "solid");
_defineProperty(ChartPropertiesName, "BAR_STYLE_GRADIENT", "gradient");
_defineProperty(ChartPropertiesName, "BAR_STYLE_OUTLINED", "outlined");
_defineProperty(ChartPropertiesName, "BAR_STYLE_GLASS", "glass");
// ---- Value Position Values — Bar / Column (value-axis direction) ----
_defineProperty(ChartPropertiesName, "VALUE_POS_OUTSIDE_END", "outside-end");
// beyond value tip (default; `auto` maps here)
_defineProperty(ChartPropertiesName, "VALUE_POS_INSIDE_END", "inside-end");
// just inside value tip
_defineProperty(ChartPropertiesName, "VALUE_POS_INSIDE_CENTER", "inside-center");
// middle of bar
_defineProperty(ChartPropertiesName, "VALUE_POS_INSIDE_START", "inside-start");
// just inside baseline
_defineProperty(ChartPropertiesName, "VALUE_POS_OUTSIDE_START", "outside-start");
// always pinned to start edge of plot area
// ---- Value Position Values — Line / Area (point-relative) ----
_defineProperty(ChartPropertiesName, "VALUE_POS_ABOVE", "above");
_defineProperty(ChartPropertiesName, "VALUE_POS_BELOW", "below");
_defineProperty(ChartPropertiesName, "VALUE_POS_CENTER", "center");
// ---- Value Position Values — Pie / Doughnut ----
_defineProperty(ChartPropertiesName, "VALUE_POS_OUTSIDE", "outside");
_defineProperty(ChartPropertiesName, "VALUE_POS_INSIDE", "inside");
_defineProperty(ChartPropertiesName, "VALUE_POS_LEGEND", "legend");

var _description = "Single source of truth for per-chart metadata. Every chart entry is fully self-contained — no inheritance. limits.series = node count (fallback if menu template lacks nodecount); limits.seriesItems = number of values per series (multi-series count, registry-authoritative). `floaterChartType` is the EXACT chartType key the host floater's secondTabData switch matches against — variants that share a settings panel collapse to the same value (e.g. all column variants → \"column\"); variants with a dedicated settings panel carry their own classname (e.g. polarAreaChart, kagiChart, dumbbellChart). Lib publishes this on outline data → PropertiesModel stores it on element.floaterChartType → host getRawChartType reads it first. Draft 2026-05-19 / floaterChartType added 2026-05-20.";
